<template><div class="page"><div class="container checkout"><section><div class="eyebrow">01 — SHIPPING</div><h1 class="h2">Where should we deliver?</h1><form @submit.prevent="next" class="form"><input v-model="form.fullName" class="input" placeholder="Full name" required/><input v-model="form.phone" class="input" placeholder="Phone number" required/><input v-model="form.line1" class="input" placeholder="Address" required/><div class="two"><input v-model="form.city" class="input" placeholder="City" required/><input v-model="form.governorate" class="input" placeholder="Governorate" required/></div><button class="btn">Continue to payment</button></form></section><OrderSummary/></div></div></template>
<script setup lang="ts">import { reactive } from 'vue';import { useRouter } from 'vue-router';import OrderSummary from './OrderSummary.vue';const router=useRouter();const form=reactive({fullName:'',phone:'',line1:'',city:'',governorate:''});function next(){sessionStorage.setItem('vora_shipping',JSON.stringify(form));router.push('/checkout/payment')}</script>
